import Link from "next/link";
import { notFound } from "next/navigation";
import areas from "../../../data/service-areas.json";
import RoavioLayout from "@/layout/RoavioLayout";

export default async function CityServicesPage({ params }) {
  const { city } = await params;

  const area = areas.find((item) => item.city == city);
  console.log("area"+area)

  if (!area) {
    notFound();
  }

  return (
    <RoavioLayout>
    <main>
      <Link href="/service-areas">← All Service Areas</Link>

      <h1>Tour Guide Services in {area.name}</h1>
      <p>{area.description}</p>

      <div className="cards-grid">
        {area.services.map((service) => (
          <Link
            key={service.slug}
            href={`/tour-areas/${area.city}/${service.slug}`}
            className="service-card"
          >
            <h2>{service.name}</h2>
            <p>{service.summary}</p>
            <p>Duration: {service.duration}</p>
            <span>View Details →</span>
          </Link>
        ))}
      </div>
    </main>
    </RoavioLayout>
  );
}